\documentclass[tikz,border=10pt]{standalone}

\usepackage[most]{tcolorbox}
\usepackage{amsmath,amssymb}
\usepackage{booktabs}
\usepackage{graphicx}

% Required TikZ libraries
\usetikzlibrary{positioning,arrows.meta}

% Colors
\definecolor{bgDark}{HTML}{101418}
\definecolor{panelBlue}{HTML}{1C2E4A}
\definecolor{accentTeal}{HTML}{2B908E}
\definecolor{accentYellow}{HTML}{F2B134}
\definecolor{accentRed}{HTML}{D64545}
\definecolor{accentGreen}{HTML}{3FA45B}
\definecolor{textLight}{HTML}{F5F5F5}

% Global settings
\pagecolor{bgDark}

\tikzset{
    mainbox/.style={
        draw=accentTeal,
        fill=panelBlue,
        thick,
        rounded corners=2mm,
        text width=14cm,
        align=center,
        inner sep=4mm,
        text=textLight
    },
    smallbox/.style={
        draw=accentTeal,
        fill=black!40,
        thick,
        rounded corners=1mm,
        align=center,
        inner sep=2mm,
        font=\scriptsize,
        text=textLight
    },
    seqbox/.style={
        draw=accentTeal,
        fill=panelBlue,
        thick,
        rounded corners=1mm,
        align=center,
        font=\scriptsize,
        minimum height=1.2cm,
        minimum width=1.8cm,
        text=textLight
    },
    titlebox/.style={
        draw=accentTeal,
        fill=bgDark,
        thick,
        rounded corners=2mm,
        text width=14cm,
        align=center,
        inner sep=3mm,
        text=textLight
    }
}

\begin{document}

\begin{tikzpicture}[text=textLight]

% ================= TITLE =================
\node[text width=15cm, align=center] (title) at (0,14) {
    \Huge\textbf{FDE \(\xrightarrow{\text{classical evaluation}}\) QM}\\[0.2cm]
    \Large\textcolor{accentTeal}{
        DQI as the Classical-Logical Image of the SIXTEEN\_3 Trilattice
    }\\[0.1cm]
    \large
    \(\mu \circ \delta = \operatorname{id}\) --- Lean 4 verified
};

% ================= 1. CORE CLAIM =================
\node[titlebox, below=0.5cm of title] (core) {
    \textbf{\large Core Claim}\\[0.2cm]
    Quantum mechanics arises when the underlying FDE/Belnap structure is
    evaluated classically rather than paraconsistently. The DQI circuit is
    therefore the classical-logical image of an IMASM word on the
    Belnap/SIXTEEN\_3 trilattice, with its apparent quantum behavior produced
    by the loss of the native paraconsistent evaluation.
};

% ================= 2. FOUR HIDDEN FOUNDATIONS =================
\node[below=0.8cm of core] (s1) {
    \Large\textbf{1. Four hidden foundations}
};

\node[
    smallbox,
    text width=3cm,
    below=0.4cm of s1,
    xshift=-5.5cm
] (f1) {
    \textbf{1. Belnap four-valued carrier}\\
    \scriptsize
    16 states, base values (T, F, U, \(\emptyset\));
    orders \(\leq_T,\leq_F,\leq_C\)
};

\node[
    smallbox,
    text width=3cm,
    below=0.4cm of s1,
    xshift=-1.8cm
] (f2) {
    \textbf{
        2. \(f_{\text{fuse}}
        \circ
        f_{\text{split}}
        =
        \operatorname{id}_{\text{Belnap}}\)
    }\\
    \scriptsize
    state preparation / measurement round-trip is identity
};

\node[
    smallbox,
    text width=3cm,
    below=0.4cm of s1,
    xshift=1.8cm
] (f3) {
    \textbf{
        3. Composition rule:
        \(\delta\) before \(\delta\),
        \(\mu\) after \(\mu\)
    }\\
    \scriptsize
    open the frame that holds the result before the frame that computes it
};

\node[
    smallbox,
    text width=3cm,
    below=0.4cm of s1,
    xshift=5.5cm
] (f4) {
    \textbf{4. Kernel teaches the repair rule}\\
    \scriptsize
    banking preserves the count across AREV
};

% ================= 3. KERNEL-VERIFIED IMASM WORD =================
\node[
    below=1.5cm of f3,
    xshift=-1.8cm
] (s2) {
    \Large\textbf{2. Kernel-verified IMASM word}
};

\node[
    seqbox,
    below=0.4cm of s2,
    xshift=-6.2cm
] (step1) {
    open outer frame
};

\node[seqbox, right=0.2cm of step1] (step2) {
    open inner frame
};

\node[seqbox, right=0.2cm of step2] (step3) {
    deposit constraints
};

\node[seqbox, right=0.2cm of step3] (step4) {
    fuse inner
};

\node[seqbox, right=0.2cm of step4] (step5) {
    AREV / uncompute
};

\node[seqbox, right=0.2cm of step5] (step6) {
    fuse outer
};

\node[seqbox, right=0.2cm of step6] (step7) {
    closure
};

\draw[-Stealth,accentTeal] (step1) -- (step2);
\draw[-Stealth,accentTeal] (step2) -- (step3);
\draw[-Stealth,accentTeal] (step3) -- (step4);
\draw[-Stealth,accentTeal] (step4) -- (step5);
\draw[-Stealth,accentTeal] (step5) -- (step6);
\draw[-Stealth,accentTeal] (step6) -- (step7);

\node[
    smallbox,
    text width=7cm,
    below=0.8cm of step4,
    draw=accentYellow
] (fail) {
    \textbf{\color{accentRed}Failed first attempt}\\
    \scriptsize
    \(
        \vdash
        \top \leftarrow
        \top \leftarrow
        \top \leftarrow
        \top \leftarrow
        \top
    \)\\
    \scriptsize
    Banked = 3 units cleared with nothing banked behind them
};

% ================= 4. FIVE UNRAVELINGS =================
\node[below=1.2cm of fail] (s3) {
    \Large\textbf{3. Five unravelings}
};

\node[
    smallbox,
    text width=2.6cm,
    below=0.4cm of s3,
    xshift=-5.5cm
] (u1) {
    \textbf{A. QFT = \(\leq_T\) info-order}\\
    \scriptsize
    Constructive interference is the classically evaluated image of upward
    movement in the information lattice.
};

\node[
    smallbox,
    text width=2.6cm,
    below=0.4cm of s3,
    xshift=-2.75cm
] (u2) {
    \textbf{B. Hamming weight = \(\leq_C\) truth-order}\\
    \scriptsize
    \(|y| \leq \ell\) is a cardinality bound on active base values in the
    16\_3 register.
};

\node[
    smallbox,
    text width=2.6cm,
    below=0.4cm of s3,
    xshift=0cm
] (u3) {
    \textbf{C. Syndrome decoding = nested \(\delta\)/\(\mu\)}\\
    \scriptsize
    Parity check and uncomputation require exact frame nesting.
};

\node[
    smallbox,
    text width=2.6cm,
    below=0.4cm of s3,
    xshift=2.75cm
] (u4) {
    \textbf{D. ``Quantum speedup'' = classical-evaluation artifact}\\
    \scriptsize
    The apparent quantum advantage is produced when FDE/trilattice order is
    evaluated under classical constraints.
};

\node[
    smallbox,
    text width=2.6cm,
    below=0.4cm of s3,
    xshift=5.5cm
] (u5) {
    \textbf{E. 5-step DQI prep = one underlying word}\\
    \scriptsize
    The circuit description is the classical-logical image of a single
    verified IMASM word.
};

% ================= 5. IMASM OPERATIONS -> DQI IMAGE =================
\node[below=1.8cm of u3] (s4) {
    \Large\textbf{4. IMASM operations \(\rightarrow\) classically evaluated DQI image}
};

\node[mainbox, below=0.4cm of s4] (table) {
    \resizebox{13.3cm}{!}{%
        \begin{tabular}{@{}l l l l l l@{}}
            \toprule

            \textbf{Step}
            & \textbf{Underlying state}
            & \textbf{Constraint deposit}
            & \textbf{Frame computation}
            & \textbf{AREV}
            & \textbf{Classical/QM image} \\

            \midrule

            1
            & \(\bigcirc\) IMSCRIB
            & \(T \perp\)
            & \(\epsilon \epsilon\)
            & \(\varnothing\)
            & Hadamard/basis: \(T\ T\) \\

            2
            & Seed \(B=(T,F)\)
            & Deposit truth/falsity
            & Open outer/inner
            & Uncompute
            & Fuse inner/outer \\

            3
            & Banked?
            & Deposit
            & Redeposit
            & Requires banking
            & Closure \\

            \bottomrule
        \end{tabular}%
    }
};

% ================= 6. KERNEL VERDICT =================
\node[below=1.2cm of table] (s5) {
    \Large\textbf{5. Kernel verdict}
};

\node[
    smallbox,
    text width=2.2cm,
    below=0.4cm of s5,
    xshift=-5.5cm
] (v1) {
    \textbf{2 deposits}
};

\node[
    smallbox,
    text width=2.2cm,
    below=0.4cm of s5,
    xshift=-2.75cm
] (v2) {
    \textbf{2 cleared}
};

\node[
    smallbox,
    text width=2.2cm,
    below=0.4cm of s5,
    xshift=0cm
] (v3) {
    \textbf{2 restored}
};

\node[
    smallbox,
    text width=2.2cm,
    below=0.4cm of s5,
    xshift=2.75cm
] (v4) {
    \textbf{2 banked}\\
    \scriptsize \(T F\)
};

\node[
    smallbox,
    text width=2.2cm,
    below=0.4cm of s5,
    xshift=5.5cm
] (v5) {
    \textbf{13 periods}
};

% ================= 7. DIALECTIC VERDICT =================
\node[
    titlebox,
    below=1.2cm of v3
] (final) {
    \textbf{\large Dialectic verdict}\\[0.2cm]
    Quantum mechanics is not fundamental in this account. It is what results
    when FDE is evaluated under classical logical constraints instead of its
    native paraconsistent semantics. The DQI quantum algorithm is thus the
    classically evaluated image of an IMASM word on the Belnap/SIXTEEN\_3
    carrier. Restoring paraconsistent evaluation exposes the underlying
    composition, banking, and trilattice-order mechanism directly.
};

% ================= FOOTER =================
\node[
    below=0.4cm of final,
    font=\scriptsize\color{accentTeal}
] (foot) {
    Lean 4 anchors:
    BelnapSplitFuse.lean
    \(\cdot\)
    Frobenius.lean \S6
    \(\cdot\)
    BankedWeight.lean
};

\end{tikzpicture}

\end{document}

